#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int t;    cin >> t;     while (t--) {        int n;        cin >> n;         vector<pair<int,int>> a(n); // {visits, index}        for (int i = 0; i < n; i++) {            cin >> a[i].first;            a[i].second = i;        }         // sort descending by visits        sort(a.rbegin(), a.rend());         vector<int> pos(n + 1);        pos[0] = 0;         int left = -1, right = 1;        long long total = 0;         for (int i = 0; i < n; i++) {            int visits = a[i].first;            int idx = a[i].second;             if (i % 2 == 0) {                pos[idx + 1] = right;                total += 2LL * abs(right) * visits;                right++;            } else {                pos[idx + 1] = left;                total += 2LL * abs(left) * visits;                left--;            }        }         cout << total << "\n";        for (int i = 0; i <= n; i++) {            cout << pos[i] << " ";        }        cout << "\n";    }}